                        /** @description Otomatik IVR arama kampanyasının adı. */
                        ivr_campaign_name?: string;
                        /** @description Kampanyadaki numaranın ID'si. */
                        ivr_lead_id?: number;
                        /** @description Aranan telefon numarası. */
                        phone?: string;
                        /** @description Aranan kişinin yaptığı tuşlama. Boş string (""): Çağrı başlamadı. 0-9: Geçerli tuşlama. -: timeout. !4: Geçersiz tuşlama. */
                        digit?: string;
